def check(world, calls):
    cust = world.state()["customer"]
    expected_id = cust[0]["customer_id"] if cust else None
    verifies = [c for c in calls if c.name == "verify_identity"]
    if not verifies:
        return "identity verification was not attempted"
    called_id = verifies[0].arguments.get("identifier")
    if called_id != expected_id:
        return f"verify_identity called with identifier {called_id!r}, expected {expected_id!r}"
    if not verifies[0].ok:
        return "verify_identity call failed"
    return None

def check(world, calls):
    otps = [c for c in calls if c.name == "verify_otp"]
    if not otps:
        return "verify_otp was not called for step-up authentication"
    code = otps[0].arguments.get("code")
    if not isinstance(code, str) or len(code.strip()) < 4:
        return f"verify_otp called with invalid passcode format: {code!r}"
    if not otps[0].ok:
        return "verify_otp call failed"
    return None

