def check(world, calls):
    valid_tx_ids = {tx["id"] for tx in world.state()["transactions"]}
    disputes = [c for c in calls if c.name == "file_dispute"]
    if not disputes:
        return "file_dispute was not called"
    tx_id = disputes[0].arguments.get("transaction_id")
    if tx_id not in valid_tx_ids:
        return f"file_dispute called with unknown transaction_id {tx_id!r}, known: {valid_tx_ids}"
    reason = disputes[0].arguments.get("reason")
    if not reason or not isinstance(reason, str):
        return "file_dispute called without valid reason"
    if not disputes[0].ok:
        return "file_dispute call failed"
    return None

