def check(world, calls):
    kb_queries = [kb["query"].lower() for kb in world.state()["kb_articles"]]
    searches = [c for c in calls if c.name == "search_kb"]
    if not searches:
        return "search_kb was not called"
    q = str(searches[0].arguments.get("query", "")).lower()
    if not any(k in q or q in k for k in kb_queries):
        return f"search_kb query {q!r} does not match any known topic ({kb_queries})"
    if not searches[0].ok:
        return "search_kb call failed"
    return None

